    /**
     * The player's volume, 0 to 1 (for presence, remote control and handoff).
     */
    fun `setVolumeLevel`(`level`: kotlin.Double)
    
    fun `stopRemoteControl`()
    
    /**
     * The device's biometrics changed: every PIN is needed once before biometric
