    /**
     * Clear list (Not interested has its own; Reset suggestions leaves it).
     */
    fun `clearNotInterested`()
    
    fun `fewerLikeThis`(`songId`: kotlin.Long)
    
    /**
     * Hide a mix from today's set (Undo: `unhide_mix`).
     */
    fun `hideMix`(`mixId`: kotlin.String)
    
    /**
     * Home (the surfaces table of section 21): Made for you, Rediscover, Recently
     * played, Deep Cuts, Recently added and Most played. Builds today's mixes when
     * due (up to `smartPicks.budgets.mixBuildSeconds`). Async.
     */
    suspend fun `home`(): Home
    
    /**
     * A mix's page (board 15), each song with one reason.
     */
    fun `mix`(`mixId`: kotlin.String): MixPage
    
    /**
     * More like this (+1.5 for the song and its neighbours here; not a like) or
     * Fewer like this (-1). Show a one-line confirmation.
     */
    fun `moreLikeThis`(`songId`: kotlin.Long)
    
    /**
     * Not in this mix (board 15, item 5): the song leaves the mix and the mix's
     * mood learns it doesn't fit (Fewer like this at this time of day).
     */
    fun `notInThisMix`(`mixId`: kotlin.String, `songId`: kotlin.Long)
    
    /**
     * Not interested in an artist: none of their songs are suggested.
     */
    fun `notInterestedArtist`(`artist`: kotlin.String, `reason`: NotInterestedReason): NotInterestedItem
    
    /**
     * Settings, Not interested.
     */
    fun `notInterestedList`(): List<NotInterestedItem>
    
    /**
     * Not interested in a song (board 38): it leaves every smart surface at once
     * but still plays when picked. Undo for 5 s with `remove_not_interested`.
     */
    fun `notInterestedSong`(`songId`: kotlin.Long, `reason`: NotInterestedReason): NotInterestedItem
    
    /**
     * Pin (kept past tomorrow; up to 10) or unpin a mix.
     */
    fun `pinMix`(`mixId`: kotlin.String, `pinned`: kotlin.Boolean)
    
    /**
     * Fill Autoplay now with 10 songs seeded by the current song and the last ones
     * finished (the core also does this by itself when fewer than 5 are
     * upcoming). Only the Autoplay section changes; songs the user queued are
     * never touched.
     */
    fun `refreshAutoplay`(): QueueState
    
    /**
     * A new set now (Regenerate). Async.
     */
    suspend fun `regenerateMixes`(): Home
    
    /**
     * Undo, or remove from Settings' list.
     */
    fun `removeNotInterested`(`item`: NotInterestedItem)
    
    /**
     * Reset suggestions (board 38, note 5): a new learning epoch. Plays and
     * feedback before now stop counting; likes, playlists, history and the Not
     * interested list stay. Syncs as a tombstone no device can undo.
     */
    fun `resetSuggestions`()
    
    /**
     * Save as playlist (board 15): a normal playlist with the mix's songs and
     * title, written to the media server like any other.
     */
    fun `saveMixAsPlaylist`(`mixId`: kotlin.String): EditResult
    
    /**
     * How adventurous (board 38); applies from the next refill.
     */
    fun `setAdventurousness`(`level`: Adventurousness)
    
    /**
     * Smart shuffle (section 21, New): the list shuffled, with one suggestion
     * after every 4 songs. Suggestions have `chosen_by` App (show the spark mark;
     * a swipe removes one).
     */
    fun `smartShuffle`(`songIds`: List<kotlin.Long>, `startedFrom`: StartedFrom, `contextId`: kotlin.String?): QueueState
    
    /**
     * Radio from a song, album, artist or playlist (section 21): it plays the
     * seed, then Autoplay keeps the seed for the whole session.
     */
    fun `startRadio`(`seed`: RadioSeed, `id`: kotlin.Long): QueueState
    
    /**
     * How suggestions are doing (board 38, note 7): local, the last 4 weeks.
     */
    fun `suggestionStats`(): SuggestionStats
    
    /**
     * Why this song (board 38): one or two reasons and up to two "sounds like".
     */
    fun `whyThisSong`(`songId`: kotlin.Long): WhyThisSong
    
    companion object
}

/**
 * The Encore core. Create one per app.
 */
open class EncoreCore: Disposable, AutoCloseable, EncoreCoreInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }
    /**
     * Start the core. `config.data_dir` must be a folder the app can write.
     */
    constructor(`config`: CoreConfig) :
        this(UniffiWithHandle, 
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_constructor_encorecore_new(
    
        
        FfiConverterTypeCoreConfig.lower(`config`),_status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_encore_core_fn_free_encorecore(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_encore_core_fn_clone_encorecore(handle, status)
        }
    }

    
    /**
     * Save a query (the return key). Recent searches stay on this device.
     */
    @Throws(EncoreException::class)override fun `addRecentSearch`(`query`: kotlin.String)
        = 
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_add_recent_search(
        it,
        
        FfiConverterString.lower(`query`),_status)
}
    }
    
    

    
    /**
     * Add songs to a playlist, a new playlist, Liked Songs or the queue: **one
     * call** with the whole list in the order shown, one event, one undo entry,
     * however many songs (section 26). `position` is the line in a playlist or in
     * Up Next (None: the end). Duplicates (by song) are skipped unless
     * `allow_duplicates` ("Add anyway"). Works offline: the change shows at once
     * and is sent when the server can be reached. Synchronous; sending happens in
     * the background.
     */
    @Throws(EncoreException::class)override fun `addTo`(`target`: DropTarget, `songIds`: List<kotlin.Long>, `position`: kotlin.UInt?, `allowDuplicates`: kotlin.Boolean): EditResult {
            return FfiConverterTypeEditResult.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_add_to(
        it,
        
        FfiConverterTypeDropTarget.lower(`target`),
        FfiConverterSequenceLong.lower(`songIds`),
        FfiConverterOptionalUInt.lower(`position`),
        FfiConverterBoolean.lower(`allowDuplicates`),_status)
}
    }
    )
    }
    

    
    @Throws(EncoreException::class)override fun `addToUpNext`(`songIds`: List<kotlin.Long>): QueueState {
            return FfiConverterTypeQueueState.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_add_to_up_next(
        it,
        
        FfiConverterSequenceLong.lower(`songIds`),_status)
}
    }
    )
    }
    

    
    @Throws(EncoreException::class)override fun `album`(`albumId`: kotlin.Long): AlbumDetail {
            return FfiConverterTypeAlbumDetail.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_album(
        it,
        
        FfiConverterLong.lower(`albumId`),_status)
}
    }
    )
    }
    

    
    /**
     * The colours for an album's gradient (board 04); None when it has no cover
     * (use the profile accent). Made once per cover from a small PNG of it, the same
     * on every device; made again when the cover changes. Works offline once made;
     * when the server can't be reached the last palette is used. Async.
     */
    @Throws(EncoreException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `albumPalette`(`albumId`: kotlin.Long) : ArtworkPalette? {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_encore_core_fn_method_encorecore_album_palette(
                uniffiHandle,
                
        FfiConverterLong.lower(`albumId`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_encore_core_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_encore_core_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.ffi_encore_core_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterOptionalTypeArtworkPalette.lift(it) },
        // Error FFI converter
        EncoreException.ErrorHandler,
    )
    }

    
    @Throws(EncoreException::class)override fun `albums`(`sort`: AlbumSort, `offset`: kotlin.UInt, `limit`: kotlin.UInt): List<AlbumSummary> {
            return FfiConverterSequenceTypeAlbumSummary.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_albums(
        it,
        
        FfiConverterTypeAlbumSort.lower(`sort`),
        FfiConverterUInt.lower(`offset`),
        FfiConverterUInt.lower(`limit`),_status)
}
    }
    )
    }
    

    
    /**
     * Whether each song is liked, in order (the heart on rows and Now Playing).
     */
    @Throws(EncoreException::class)override fun `areLiked`(`songIds`: List<kotlin.Long>): List<kotlin.Boolean> {
            return FfiConverterSequenceBoolean.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_are_liked(
        it,
        
        FfiConverterSequenceLong.lower(`songIds`),_status)
}
    }
    )
    }
    

    
    @Throws(EncoreException::class)override fun `artist`(`artistId`: kotlin.Long): ArtistDetail {
            return FfiConverterTypeArtistDetail.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_artist(
        it,
        
        FfiConverterLong.lower(`artistId`),_status)
}
    }
    )
    }
    

    
    @Throws(EncoreException::class)override fun `artistSongs`(`artistId`: kotlin.Long, `offset`: kotlin.UInt, `limit`: kotlin.UInt): List<Song> {
            return FfiConverterSequenceTypeSong.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_artist_songs(
        it,
        
        FfiConverterLong.lower(`artistId`),
        FfiConverterUInt.lower(`offset`),
        FfiConverterUInt.lower(`limit`),_status)
}
    }
    )
    }
    

    
    @Throws(EncoreException::class)override fun `artists`(`offset`: kotlin.UInt, `limit`: kotlin.UInt): List<ArtistSummary> {
            return FfiConverterSequenceTypeArtistSummary.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_artists(
        it,
        
        FfiConverterUInt.lower(`offset`),
        FfiConverterUInt.lower(`limit`),_status)
}
    }
    )
    }
    

    
    /**
     * The image for an item at exactly `size_px` (plan section 4).
     */
    @Throws(EncoreException::class)override fun `artwork`(`of`: ArtworkOf, `id`: kotlin.Long, `sizePx`: kotlin.UInt): ArtworkRequest {
            return FfiConverterTypeArtworkRequest.lift(
    callWithHandle {
    uniffiRustCallWithError(EncoreException) { _status ->
    UniffiLib.uniffi_encore_core_fn_method_encorecore_artwork(
        it,
        
        FfiConverterTypeArtworkOf.lower(`of`),
